from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
# find horizontal scanline edge positions based color delta median over 1D
for y in range(280,650,5):
 p=im[y].astype(int)
 d=np.abs(p-np.roll(p,20,axis=0)).sum(1)
 # smooth and peaks
 d=np.convolve(d,np.ones(5)/5,'same')
 peaks=[]
 for x in range(40,1240):
  if d[x]>40 and d[x]>=d[x-5] and d[x]>=d[x+5]:peaks.append(x)
 # merge
 out=[]
 for x in peaks:
  if not out or x-out[-1]>20:out.append(x)
 if out:print(y,out[:30])
